import{_ as t,o as a,c as r,au as o}from"./chunks/framework.yLMVpebq.js";const p=JSON.parse('{"title":"DPIAs and data applications","description":"A consolidated reference for researchers who need to describe how data is stored and processed in HUNT Cloud when writing DPIAs and applications for data access.","frontmatter":{"title":"DPIAs and data applications","category":"Administer science","permalink":"/administer-science/dpia-and-data-applications","outline":1,"description":"A consolidated reference for researchers who need to describe how data is stored and processed in HUNT Cloud when writing DPIAs and applications for data access."},"headers":[],"relativePath":"administer-science/dpia-and-data-applications.md","filePath":"administer-science/dpia-and-data-applications.md"}'),s={name:"administer-science/dpia-and-data-applications.md"};function i(n,e,c,d,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="dpias-and-data-applications" tabindex="-1">DPIAs and data applications <a class="header-anchor" href="#dpias-and-data-applications" aria-label="Permalink to &quot;DPIAs and data applications&quot;">​</a></h1><p><strong>This page gathers, in one place, the information you most often need to describe how your data is stored and processed in HUNT Cloud. It is written for the scientists — postdocs, principal investigators and PhD students — who write Data Protection Impact Assessments (DPIAs) and applications for data access (&quot;request for data&quot;), and who need to document our security level, certificates and access controls for their data controllers.</strong></p><nav class="table-of-contents"><ul><li><a href="#a-short-description-you-can-adapt">A short description you can adapt</a></li><li><a href="#where-your-data-lives">Where your data lives</a></li><li><a href="#security-levels-and-data-classification">Security levels and data classification</a></li><li><a href="#access-security-and-two-factor-login">Access security and two-factor login</a></li><li><a href="#iso-certificates">ISO certificates</a></li><li><a href="#norwegian-legal-framework-and-terminology">Norwegian legal framework and terminology</a></li><li><a href="#data-protection-impact-assessment-dpia">Data Protection Impact Assessment (DPIA)</a></li><li><a href="#what-institutions-often-ask-for">What institutions often ask for</a></li><li><a href="#documents-you-can-cite">Documents you can cite</a></li></ul></nav><div class="tip custom-block"><p class="custom-block-title">Let us help</p><p>The fastest path to a precise text is to let us comment on your draft. We are more than happy to assist with information, clarifications and a review of your DPIAs and data applications. <a href="/contact">Contact us</a> — and see our <a href="/govern-science/risk-management/resources">risk management resources</a> for the source documents behind this page.</p></div><h2 id="a-short-description-you-can-adapt" tabindex="-1">A short description you can adapt <a class="header-anchor" href="#a-short-description-you-can-adapt" aria-label="Permalink to &quot;A short description you can adapt&quot;">​</a></h2><p>When an application asks you to describe where and how your data is processed, you are welcome to build on the following summary and tailor it to your project:</p><blockquote><p>The data is processed in HUNT Cloud, a secure scientific cloud service owned and operated by the Norwegian University of Science and Technology (NTNU). The processing takes place in a dedicated, isolated digital laboratory (&quot;lab&quot;) running on physical servers owned by NTNU and located in data centers in Trondheim, Norway. Access requires an encrypted VPN connection with two-factor authentication, followed by an authenticated SSH login, and data never leaves the lab unless explicitly transferred. HUNT Cloud is certified to ISO/IEC 27001 (information security), ISO/IEC 27701 (privacy information management) and ISO 9001 (quality), with the cloud-specific controls ISO/IEC 27017 and ISO/IEC 27018 included in the 27001 certificate.</p></blockquote><p>Always check the wording against your own project, your data controller&#39;s expectations and our current <a href="/govern-science/compliance/certificates">certificates</a>.</p><h2 id="where-your-data-lives" tabindex="-1">Where your data lives <a class="header-anchor" href="#where-your-data-lives" aria-label="Permalink to &quot;Where your data lives&quot;">​</a></h2><p>Your data lives inside your own digital laboratory. In short:</p><ul><li><strong>Owner and operator:</strong> HUNT Cloud is fully owned by NTNU, Norway, and affiliated with the Department of Public Health and Nursing.</li><li><strong>Location:</strong> Your virtual machines run on physical servers owned by NTNU and located in data centers in Trondheim, Norway — relevant when an application asks about data location and storage outside the EU/EEA.</li><li><strong>Isolation:</strong> Your lab is one or more Linux virtual machines with attached storage inside a dedicated private network. Resources are dedicated to your lab; lab users cannot access data or resources belonging to other labs.</li><li><strong>Entry machine:</strong> A dedicated &quot;entry&quot; machine acts as a security gateway (jump host) that every connection must pass, keeping access control separate from your scientific work.</li><li><strong>Home machine:</strong> Your analysis runs on a &quot;home&quot; machine that holds your default storage volumes, your Workbench tools (Python, RStudio, MATLAB, remote desktop) and your analytical software. Data is uploaded to, stored in and analyzed on the home machine, and <strong>does not leave the lab unless you explicitly transfer it</strong>. You can scale the home machine&#39;s compute power and add storage or extra machines as your project grows.</li></ul><h2 id="security-levels-and-data-classification" tabindex="-1">Security levels and data classification <a class="header-anchor" href="#security-levels-and-data-classification" aria-label="Permalink to &quot;Security levels and data classification&quot;">​</a></h2><p>Storage volumes in HUNT Cloud are classified by the sensitivity of the data they hold. Volumes are <strong>classified as sensitive by default</strong>.</p><table tabindex="0"><thead><tr><th>Classification</th><th>Description</th><th>Examples</th></tr></thead><tbody><tr><td><strong>Sensitive</strong></td><td>Research data that can indirectly identify research participants.</td><td>Individual-level data such as phenotype and genotype data.</td></tr><tr><td><strong>Internal</strong></td><td>Research data that can <em>not</em> identify research participants.</td><td>Summary statistics, figures, computer code, non-human data, encrypted sensitive data.</td></tr></tbody></table><p>Volumes may be declassified from sensitive to internal in agreement with the relevant data controllers and lab owners.</p><div class="tip custom-block"><p class="custom-block-title">Mapping to legal terms</p><p>HUNT Cloud&#39;s &quot;Sensitive&quot; and &quot;Internal&quot; labels are operational <em>storage</em> classifications, not legal categories. In GDPR and Norwegian terms, data that can indirectly identify participants (HUNT Cloud &quot;Sensitive&quot;) is <strong>pseudonymized personal data</strong> — still personal data, and for health or genetic data a <strong>special category</strong> (see <a href="#norwegian-legal-framework-and-terminology">legal framework</a> below). Data that can no longer identify anyone — a basis for &quot;Internal&quot; — corresponds to <strong>anonymous data</strong>, which falls outside data-protection law.</p></div><div class="warning custom-block"><p class="custom-block-title">Direct identifiers</p><p>Directly identifiable data — names, national identity numbers, phone numbers, addresses, etc. — may <strong>not</strong> be stored by default. It must be kept outside HUNT Cloud unless specifically approved in a dedicated amendment to the data processor agreement with your host organization. See the <a href="/do-science/faq/security">security FAQ</a> for details.</p></div><h2 id="access-security-and-two-factor-login" tabindex="-1">Access security and two-factor login <a class="header-anchor" href="#access-security-and-two-factor-login" aria-label="Permalink to &quot;Access security and two-factor login&quot;">​</a></h2><p>Applications and DPIAs frequently ask how we control access. Access to your lab combines several independent controls that work together:</p><ol><li><strong>Encrypted VPN.</strong> All traffic between the user&#39;s computer and HUNT Cloud runs through an encrypted OpenVPN connection, protecting the confidentiality of the data in transit.</li><li><strong>Two-factor authentication.</strong> The VPN login requires a one-time verification code (TOTP) generated every 30 seconds in an authenticator app (Google or Microsoft Authenticator) on the user&#39;s personal phone, combined with a fixed personal passphrase. This is the &quot;two-factor log-in&quot;.</li><li><strong>Authenticated SSH.</strong> After the VPN, users authenticate with SSH — first to the entry (jump host) machine, then to the home machine that holds the data and analytical tools.</li><li><strong>Out-of-band key delivery.</strong> Access keys are split across channels: certificates arrive as an encrypted 7z archive over organizational email, while the keys to unlock them are delivered separately over the encrypted Signal app to the user&#39;s registered phone.</li></ol><p>Together this means a user needs <em>something they have</em> (phone with the authenticator and Signal keys) and <em>something they know</em> (VPN passphrase and SSH credentials) to reach the data.</p><h2 id="iso-certificates" tabindex="-1">ISO certificates <a class="header-anchor" href="#iso-certificates" aria-label="Permalink to &quot;ISO certificates&quot;">​</a></h2><p>Independent auditors verify HUNT Cloud against three international management-system standards every year. Certificates and audit reports are available to data controllers on request; you can cite them directly in your application.</p><table tabindex="0"><thead><tr><th>Standard</th><th>What it covers</th></tr></thead><tbody><tr><td><strong>ISO/IEC 27001</strong></td><td>Information security management. Certified since 2017.</td></tr><tr><td><strong>ISO/IEC 27701</strong></td><td>Privacy information management (extends 27001). Certified since 2024.</td></tr><tr><td><strong>ISO 9001</strong></td><td>Quality management. Certified since 2017.</td></tr><tr><td><strong>ISO/IEC 27017</strong></td><td>Additional security controls for cloud services (included in the 27001 certificate).</td></tr><tr><td><strong>ISO/IEC 27018</strong></td><td>Additional privacy controls for cloud services (included in the 27001 certificate).</td></tr></tbody></table><p>The <strong>Statement of Applicability (SoA)</strong> lists exactly which ISO controls we apply, with their implementation status — a useful reference when an assessor wants to check specific safeguards. See the full <a href="/govern-science/compliance/certificates">certificates page</a> for downloadable PDFs, certificate IDs and the SoA, and the <a href="/govern-science/compliance/">compliance program</a> for an overview.</p><h2 id="norwegian-legal-framework-and-terminology" tabindex="-1">Norwegian legal framework and terminology <a class="header-anchor" href="#norwegian-legal-framework-and-terminology" aria-label="Permalink to &quot;Norwegian legal framework and terminology&quot;">​</a></h2><p>Applications and DPIAs are easier to write — and to get approved — when you use the terms your institution and the authorities expect:</p><ul><li><strong>Data controller (<em>behandlingsansvarlig</em>)</strong> — determines why and how personal data is processed; usually your host institution. <strong>Data processor (<em>databehandler</em>)</strong> — processes data on the controller&#39;s behalf; this is the role HUNT Cloud (NTNU) holds. The two are bound by a <strong>data processor agreement (<em>databehandleravtale</em>)</strong> — see our <a href="/govern-science/organizational-access/data-processor-agreement">data processor agreement</a>.</li><li><strong>Legal basis (<em>behandlingsgrunnlag</em>)</strong> — you must identify a lawful basis under GDPR <a href="https://gdpr-info.eu/art-6-gdpr/" target="_blank" rel="noreferrer">Article 6</a>. For health, genetic and other <strong>special categories of personal data (<em>særlige kategorier</em>)</strong> you additionally need a basis under <a href="https://gdpr-info.eu/art-9-gdpr/" target="_blank" rel="noreferrer">Article 9</a>; research typically relies on Article 9(2)(j).</li><li><strong>Special categories</strong> — <em>health data</em> and <em>genetic data</em> are special-category personal data. This is the precise legal term; HUNT Cloud&#39;s &quot;Sensitive&quot; label is the matching storage classification.</li><li><strong>Security measures (<em>tekniske og organisatoriske tiltak</em>)</strong> — GDPR <a href="https://gdpr-info.eu/art-32-gdpr/" target="_blank" rel="noreferrer">Article 32</a> requires appropriate technical and organizational measures. The isolation, access controls, encryption and certificates described above are what you cite here.</li></ul><p>These rules reach Norwegian law through the <strong>Personal Data Act (<em>personopplysningsloven</em>)</strong>, which incorporates the GDPR. Medical and health research carries additional requirements:</p><ul><li><strong>Health Research Act (<em>helseforskningsloven</em>)</strong> — research on people, human biological material or personal health data needs prior approval from a <strong>Regional Committee for Medical and Health Research Ethics (REK)</strong> before it can start.</li><li><strong>Notification and advice</strong> — projects processing personal data are normally notified to <strong><a href="https://sikt.no/en/data-protection-services" target="_blank" rel="noreferrer">Sikt</a></strong> (the data-protection service for most Norwegian institutions, formerly NSD), and your institution&#39;s <strong>Data Protection Officer (<em>personvernombud</em>, DPO)</strong> advises on and signs off DPIAs.</li></ul><h2 id="data-protection-impact-assessment-dpia" tabindex="-1">Data Protection Impact Assessment (DPIA) <a class="header-anchor" href="#data-protection-impact-assessment-dpia" aria-label="Permalink to &quot;Data Protection Impact Assessment (DPIA)&quot;">​</a></h2><p>A DPIA may be required before processing begins where it is likely to result in a high risk to individuals&#39; rights — for example large-scale processing of special-category (health or genetic) data. The duty comes from GDPR <a href="https://gdpr-info.eu/art-35-gdpr/" target="_blank" rel="noreferrer">Article 35</a>, incorporated through the Personal Data Act (<em>personopplysningsloven</em>); the Norwegian term is <em>personvernkonsekvensvurdering</em>. A few points worth knowing:</p><ul><li><strong>You write the assessment.</strong> There is no standardized text to copy — you must assess the risks relevant to your specific scientific context. We are happy to share and discuss scenarios, threats and assessments, and to comment on your drafts.</li><li><strong>Residual risk.</strong> No system removes all risk. Whatever remains after security and privacy controls are in place is the <em>residual risk</em>, and it must be formally accepted.</li><li><strong>Risk owner.</strong> The person with the authority to accept residual risk on behalf of the data and/or organization is the <em>risk owner</em>. You document your assessment and inform the risk owner of any residual risks; they accept the risk or require further reduction before the service is used.</li><li><strong>Risk assessment reports (RAR).</strong> Your organization may also request a security/privacy risk assessment (&quot;ROS-analyse&quot;). We share our own internal RAR with data controllers on request.</li></ul><p>See the <a href="/govern-science/risk-management/">risk management</a> section and its <a href="/govern-science/risk-management/faq">FAQ</a> for more.</p><h2 id="what-institutions-often-ask-for" tabindex="-1">What institutions often ask for <a class="header-anchor" href="#what-institutions-often-ask-for" aria-label="Permalink to &quot;What institutions often ask for&quot;">​</a></h2><p>DPIA templates and data-application forms tend to ask the same questions. To help you move quickly, here is where to find our answer to each of them:</p><table tabindex="0"><thead><tr><th>The form asks about…</th><th>Where to find it</th></tr></thead><tbody><tr><td>Where data is processed/stored (and whether outside the EU/EEA)</td><td><a href="#where-your-data-lives">Where your data lives</a> — NTNU data centers in Norway.</td></tr><tr><td>Data processor and processor agreement</td><td><a href="#norwegian-legal-framework-and-terminology">Legal framework</a>; the <a href="/govern-science/organizational-access/data-processor-agreement">data processor agreement</a>.</td></tr><tr><td>Technical and organizational security measures (Art. 32)</td><td><a href="#access-security-and-two-factor-login">Access security</a>, the <a href="/administer-science/services/specifications">services specifications</a> and the <a href="/govern-science/compliance/certificates#statement-of-applicability-soa">SoA</a>.</td></tr><tr><td>Access control and authentication</td><td><a href="#access-security-and-two-factor-login">Access security and two-factor login</a>.</td></tr><tr><td>Certificates / independent assurance</td><td><a href="#iso-certificates">ISO certificates</a>.</td></tr><tr><td>Sub-processors / subcontractors</td><td><a href="/govern-science/compliance/subcontractors">Subcontractors</a>.</td></tr><tr><td>Encryption</td><td>Encrypted VPN in transit; <a href="/administer-science/data/tape-service/">tape service</a> for encrypted offsite copies.</td></tr><tr><td>Backup, restore and deletion</td><td><a href="/administer-science/data/faq">Data administrator FAQ</a>.</td></tr><tr><td>Incident / data-breach handling</td><td><a href="/do-science/faq/security">Security FAQ</a>.</td></tr><tr><td>Logging and auditability</td><td>We log access and transfers; logs are available to data controllers on request — <a href="/contact">contact us</a>.</td></tr></tbody></table><h2 id="documents-you-can-cite" tabindex="-1">Documents you can cite <a class="header-anchor" href="#documents-you-can-cite" aria-label="Permalink to &quot;Documents you can cite&quot;">​</a></h2><p>These are the public documents that we are happy for you to reference directly in your assessments and applications:</p><table tabindex="0"><thead><tr><th>Document</th><th>Use it to show…</th></tr></thead><tbody><tr><td><a href="/govern-science/compliance/certificates">ISO certificates</a></td><td>Independent verification of our security, privacy and quality management.</td></tr><tr><td><a href="/govern-science/compliance/certificates#statement-of-applicability-soa">Statement of Applicability (SoA)</a></td><td>Which specific ISO controls are implemented.</td></tr><tr><td><a href="/govern-science/policies/">Security and privacy policies</a></td><td>The framework of individual controls we commit to.</td></tr><tr><td><a href="/administer-science/services/specifications">Services specifications</a></td><td>Responsibilities and security/privacy measures per service.</td></tr><tr><td><a href="/administer-science/privacy-statement">Privacy statement</a></td><td>How HUNT Cloud handles personal data.</td></tr><tr><td><a href="/govern-science/risk-management/resources">Risk management resources</a></td><td>The full set of resources behind risk assessments.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Need something not listed here?</p><p>We hold an extensive collection of additional security documentation that is not published on these pages. It is available to data controllers on request under some conditions. <a href="/contact">Contact us</a> for your assessments.</p></div>',41)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
